custom_css:
/* 一本笔记本_今日小雪@夜行性鲨鱼
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎……给我吃一口吧！
带符号🤍的地方是可以自定义的区域 */
body,#bg1{margin:0!important;padding:0!important;background-color:transparent!important}
::-webkit-scrollbar{display:none}
#sheld,#form_sheld,.top-bar-border{border:none!important;box-shadow:none!important;background:transparent!important}
/* 核心精修：增加上下自然渐隐蒙版 */
#chat{border:none!important;box-shadow:none!important;background:transparent!important;padding-top:25px!important;padding-bottom:80px!important;gap:40px!important;-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 30px),transparent 100%)!important;mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 30px),transparent 100%)!important}

/* 1.核心气泡 */
#chat .mes{position:relative!important;background:#fff!important;width:93%!important;max-width:860px!important;margin:0 auto!important;padding:30px 35px 40px 50px!important;border:1px solid #ececec!important;border-radius:4px 12px 12px 4px!important;box-shadow:-2px 0 5px rgba(0,0,0,0.02),1px 1px 0 #f9f9f9,2px 2px 0 #f0f0f0,3px 3px 0 #e8e8e8,4px 4px 10px rgba(0,0,0,0.06)!important;display:flex!important;flex-direction:column!important;overflow:visible!important}
#chat .mes::after{display:none!important}
#chat .mes::before{content:""!important;display:block!important;position:absolute!important;left:8px!important;top:20px!important;bottom:20px!important;width:32px!important;background:transparent!important;background-image:repeating-linear-gradient(to bottom,transparent 0,transparent 18px,#d0d0d0 18px,#fff 19px,#a0a0a0 20px,transparent 21px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 21px,#d0d0d0 21px,#fff 22px,#a0a0a0 23px,transparent 24px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 16px,#ccc 16px,#eee 17px,#eee 25px,#ccc 26px,transparent 26px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 17px,#777 17px,#999 25px,transparent 25px,transparent 40px)!important;background-size:32px 100%,32px 100%,12px 100%,10px 100%!important;background-position:0 0,0 0,20px 0,21px 0!important;background-repeat:repeat-y!important;z-index:10}

/* 🤍2.内容包裹-可以用自己喜欢的图片替换url图链 */
#chat .mes .mes_block{display:flex!important;flex-direction:column!important;width:100%!important;padding-left:25px!important;box-sizing:border-box!important;margin:0!important;background:transparent!important;box-shadow:-15px 0 15px -15px rgba(0,0,0,0.05)!important}
#chat .mes .mes_block::before{content:"";display:block;width:100%;height:180px;border-radius:8px;background:url("https://files.catbox.moe/lc7xgw.jpg") center/cover no-repeat;margin-bottom:25px}/* 🤍char！ */
#chat .mes[is_user="true"] .mes_block::before{background-image:url("https://files.catbox.moe/3up1yg.jpg")!important}/* 🤍user！ */

/* === 核心排版修复区 (击穿酒馆DOM限制) === */
/* 3. 头像与悬浮 (完全独立，右侧锚定中轴线) */
#chat .mes .mesAvatarWrapper{display:contents!important}
#chat .mes .avatar{position:absolute!important;top:120px!important;left:calc(50% - 21px)!important;transform:translate(-100%,-50%)!important;margin-left:-6px!important;width:30px!important;height:30px!important;border-radius:50%!important;border:2px solid #fff!important;background:#fff!important;box-shadow:0 0 0 2px rgba(255,255,255,0.4), 0 2px 8px rgba(0,0,0,0.2)!important;pointer-events:auto!important;padding:0!important;z-index:7}
#chat .mes .avatar img{width:100%!important;height:100%!important;border-radius:50%!important;object-fit:cover!important}
#chat .mes .avatar::before,#chat .mes .avatar::after{display:none!important}

/* 🤍4.角色名+自定义文本 (完全独立，左侧锚定中轴线) */
#chat .mes .ch_name,
#chat .mes .ch_name .flex-container,
#chat .mes .ch_name .alignItemsBaseline{display:contents!important}

/* 防糊精修：角色名增加柔和白底光晕与强发光 */
#chat .mes .name_text{position:absolute!important;top:120px!important;left:calc(50% - 21px)!important;transform:translate(0,-50%)!important;margin-left:6px!important;font-size:18px!important;font-weight:700!important;color:#222!important;letter-spacing:.5px!important;background:radial-gradient(ellipse at center, rgba(255,255,255,0.85) 15%, transparent 75%)!important;padding:4px 15px!important;text-shadow:0 0 3px #fff, 0 0 6px #fff, 0 0 12px rgba(255,255,255,0.9), 0 2px 4px rgba(0,0,0,0.15)!important;z-index:8!important;display:flex!important;align-items:center!important;pointer-events:auto!important}
#chat .mes .name_text::before{content:"@";color:#666;font-weight:500;font-size:17px!important;margin-right:4px}

/* --- 美化升级：时间戳采用与用户名一致的发光效果 --- */
#chat .mes .timestamp{position:absolute!important;top:38px!important;left:80px!important;font-size:12px!important;color:#333!important;margin:0!important;background:radial-gradient(ellipse at center, rgba(255,255,255,0.7) 10%, transparent 80%)!important;padding:2px 6px!important;text-shadow:0 0 2px #fff, 0 0 4px #fff, 0 1px 2px rgba(0,0,0,0.2)!important;z-index:8!important;pointer-events:none!important}

/* 拦截并定位模型图标(位于时间戳右侧)防错位、防糊 */
#chat .mes .ch_name img, #chat .mes .model_logo {position:absolute!important;top:38px!important;left:245px!important;height:18px!important;width:auto!important;z-index:9!important;filter:drop-shadow(0 1px 3px rgba(0,0,0,0.8))!important;pointer-events:none!important}

/* 移除原有名字尾随占位 */
#chat .mes .ch_name>.flex-container.flex1::after{display:none!important;content:none!important}
#chat .mes .ch_name .alignItemsBaseline::after{display:none!important}
/* ========================================= */

/* 5.数据位置：极限文字美化 */
/* --- 优化：增加 :empty 判定，无内容时不显示色块背景 --- */
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{position:absolute!important;top:195px!important;font-size:11px!important;color:rgba(255,255,255,0.9)!important;background:rgba(0,0,0,0.25)!important;backdrop-filter:blur(4px)!important;-webkit-backdrop-filter:blur(4px)!important;border:none!important;box-shadow:none!important;line-height:1!important;pointer-events:auto!important;margin:0!important;z-index:6;font-weight:700!important;letter-spacing:.5px!important;-webkit-text-stroke:0!important;text-shadow:0 1px 2px rgba(0,0,0,0.7)!important;padding:2px 6px!important;border-radius:4px!important}
#chat .mes .mesIDDisplay:empty,#chat .mes .mes_timer:empty,#chat .mes .tokenCounterDisplay:empty{display:none!important}
#chat .mes .tokenCounterDisplay{right:45px!important}
#chat .mes .mes_timer{right:110px!important}
#chat .mes .mesIDDisplay{right:175px!important}


/* 6.按钮-修复菜单显示与溢出 */
#chat .mes .mes_buttons{position:absolute!important;bottom:20px!important;right:40px!important;top:auto!important;width:auto!important;height:auto!important;z-index:11;pointer-events:auto;display:flex!important;flex-direction:row!important;gap:15px!important;overflow:visible!important}
#chat .mes .mes_buttons .mes_button{display:none!important;position:relative!important;font-size:16px!important;color:#ccc!important;opacity:0;transition:opacity .2s;cursor:pointer}
#chat .mes:hover .mes_buttons .mes_button{opacity:1}
#chat .mes .mes_buttons .mes_button:hover{color:#888!important}
#chat .mes .mes_buttons .extraMesButtonsHint,#chat .mes .mes_buttons .mes_bookmark,#chat .mes .mes_buttons .mes_edit{display:block!important}
#chat .mes .mes_buttons .extraMesButtons{display:none;position:absolute;bottom:30px;right:0;background:#fff!important;border:1px solid #ececec!important;border-radius:8px;padding:8px 12px!important;box-shadow:0 4px 15px rgba(0,0,0,0.1);z-index:99;flex-direction:row!important;gap:12px!important;width:max-content}
#chat .mes .mes_buttons .extraMesButtons .mes_button{display:block!important;opacity:1!important;color:#888!important}
#chat .mes .mes_edit_buttons{position:absolute!important;bottom:45px!important;right:40px!important;background:#fff!important;border:1px solid #ececec!important;border-radius:8px;padding:6px 10px!important;box-shadow:0 4px 15px rgba(0,0,0,0.1);z-index:100;gap:8px;margin:0!important;width:max-content}
#chat .mes .mes_edit_buttons .menu_button{margin:0!important;padding:4px 8px!important}

/* 7.正文与思维链排版扩容精修 */
#chat .mes .mes_text{background-color:transparent!important;width:100%!important;margin:40px 0 0 0!important;padding:0!important;color:#555!important;line-height:1.9!important;border:none!important;font-size:14.5px!important}
#chat .mes .mes_text::after{display:none!important}

/* 🤍自定义诗句移至此处，向上吃掉距离，实现“紧贴图片”显示 */
#chat .mes .mes_text::before{content:"十二月，祝我们有世上最好的夜晚。\A火车在眼前停下，雪也在今夜停下，\A只有月亮，雪色。\A我们和睛朗力肺腑。"!important;white-space:pre-wrap!important;display:block!important;font-size:13.5px!important;color:#888!important;line-height:1.5!important;text-align:center!important;margin-top:-45px!important;margin-bottom:25px!important;letter-spacing:.5px!important}

#chat .mes .mes_text p{margin-bottom:15px!important;text-align:left!important}

/* 7.1 文本细节装饰 */
/* 7.1 引号文本-艺术档案切片美化 (设计感增强版) */
q{display:inline-block!important;background:linear-gradient(135deg,#fff,#fafafa)!important;padding:8px 18px!important;margin:15px 5px!important;color:#444!important;position:relative!important;font-style:normal!important;box-shadow:5px 5px 0 #f0f0f0!important;border:1px solid #eee!important;z-index:1!important;line-height:1.6!important}
/* 顶部元数据编号 */
q::before{content:"#☃：“天冷添衣！”"!important;position:absolute!important;top:-16px!important;left:0!important;font-size:8px!important;color:#bbb!important;letter-spacing:2px!important;font-weight:700!important}
/* 背景巨型符号：作为极浅的视觉装饰，而非文本符号 */
q::after{content:"“"!important;position:absolute!important;left:4px!important;top:2px!important;font-size:45px!important;color:rgba(0,0,0,0.03)!important;z-index:-1!important;line-height:1!important}
/* 右下角设计点缀：一条细长的对齐基准线 */
q span::after{content:""!important;position:absolute!important;right:-8px!important;bottom:5px!important;width:20px!important;height:1px!important;background:#333!important;transform:rotate(-40deg)!important}
#chat .mes .mes_text strong{position:relative!important;z-index:1!important;color:#333!important;font-weight:700!important;background:linear-gradient(to bottom,transparent 60%,rgba(176,190,200,.3) 40%)!important}
#chat .mes .mes_text em{position:relative!important;padding-left:1.0em!important;font-style:italic!important;color:#666!important;display:inline!important}
#chat .mes .mes_text em::before{content:""!important;position:absolute!important;left:0!important;top:0.12em!important;width:1em!important;height:1em!important;background:url("https://files.catbox.moe/47eio1.png") center/contain no-repeat!important;filter:drop-shadow(1px 1px 0 rgba(0,0,0,0.4)) drop-shadow(-0.5px -0.5px 0 rgba(255,255,255,0.9))!important;opacity:1!important;pointer-events:none!important}/* 🤍 */
/* 修正引号截断 */
#chat .mes .mes_text blockquote{position:relative;margin:35px 5px!important;padding:20px 40px!important;border:none!important;background:linear-gradient(90deg,rgba(0,0,0,0.03) 0%,transparent 50%)!important;color:#777!important;font-style:italic;border-left:1px solid #ddd!important;letter-spacing:0.05em;line-height:1.8}
#chat .mes .mes_text blockquote::before{content:"\201C";position:absolute;left:10px;top:-12px;font-size:52px;color:rgba(0,0,0,0.04);line-height:1;pointer-events:none}
#chat .mes .mes_text blockquote::after{content:"\201D";position:absolute;right:15px;bottom:-25px;font-size:52px;color:rgba(0,0,0,0.04);line-height:1;pointer-events:none}
/* 进修：叠纸锐化代码块 */
#chat .mes .mes_text pre,.mes_reasoning pre{background:#fdfdfd!important;color:#555!important;border:1px solid #dce2e8!important;box-shadow:2px 2px 0 rgba(176,190,200,.2)!important;margin:25px 12px 25px 0!important;padding:35px 15px 15px!important;position:relative!important;overflow:visible!important;border-radius:2px!important;width:auto!important}
#chat .mes .mes_text pre::before,.mes_reasoning pre::before{content:"到冬天去，去灯火通明处。"!important;position:absolute!important;top:-13px!important;left:15px!important;height:26px!important;padding:0 12px 0 28px!important;background:#fff url("https://files.catbox.moe/47eio1.png") no-repeat 8px center/14px!important;color:#7a8a99!important;font:italic 700 10px/26px serif!important;letter-spacing:1px!important;border:1px solid #dce2e8!important;box-shadow:1px 2px 4px rgba(0,0,0,.05)!important;border-radius:13px!important;z-index:2}/* 🤍 */
#chat .mes .mes_text pre code,.mes_reasoning pre code{background:transparent!important;color:#555!important;text-shadow:none!important}
#chat .mes .mes_text :not(pre)>code{background:#f0f0f0!important;color:#666!important;padding:2px 5px!important;border-radius:4px!important}

/* 7.2 思维链 */
.mes_reasoning_details{margin:15px 0!important;border:none!important;background:transparent!important}
.mes_reasoning_header_title{display:none!important}
.mes_reasoning_header,.mes_reasoning_summary,details.mes_reasoning_details>summary,.mes_reasoning_header_text{background:transparent!important;box-shadow:none!important}
.mes_reasoning_summary{display:flex!important;justify-content:center!important;align-items:center!important;border-top:1px dashed #ececec!important;border-bottom:1px dashed #ececec!important;padding:8px 30px!important;color:#aaa!important;font-size:12px!important;letter-spacing:2px!important;list-style:none!important}
.mes_reasoning_summary::-webkit-details-marker,.mes_reasoning_header_icon{display:none!important}
.mes_reasoning_header::before{content:"祝我们，总有笨拙的冬和相拥。"!important}/* 🤍 */
.mes_reasoning{background:rgba(0,0,0,.015)!important;color:#888!important;font-size:.85em!important;font-style:italic!important;line-height:1.8!important;padding:15px!important;border:none!important;border-left:2px solid #e0e2e5!important;border-radius:4px!important}

/* 8.UI修复 */
.standoutHeader,.title_restorable,.inline-drawer-header,#user-settings-block h4,h4[data-i18n],.persona_management_global_settings h4{background-color:#fff!important;background-image:none!important;border:1px solid #eaeaec!important;color:#555!important;border-radius:6px!important;text-shadow:none!important}
.text_pole,textarea,select,.drawer-content,.menu_button,#completion_prompt_manager_list .completion_prompt_manager_prompt_name{background-color:#fff!important;border:1px solid #e0e2e5!important;color:#555!important;border-radius:6px!important}
.range-block-counter input,.neo-range-input{background-color:#fff!important;border:1px solid #e0e2e5!important;color:#555!important;border-radius:4px!important}
#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *{color:#666!important;-webkit-text-fill-color:#666!important;text-shadow:none!important;opacity:1!important}
.text_pole:focus,textarea:focus,select:focus{border-color:#bbbcbe!important;box-shadow:0 0 0 2px rgba(0,0,0,0.04)!important;outline:none!important}
.menu_button:hover{background-color:#f5f6f7!important;color:#333!important}

/* 🤍9.底栏顶栏精修 */
#send_form{width:94%!important;max-width:860px!important;margin:0 auto 15px auto!important;background:transparent!important;border-radius:12px!important;border:none!important;box-shadow:none!important;position:relative!important}
#nonQRFormItems{position:relative!important;border-radius:12px!important}
#send_textarea{background:transparent!important;border:none!important;box-shadow:none!important;color:#444!important}
#send_textarea::placeholder{color:transparent!important}
#leftSendForm>div,#rightSendForm>div{transform:scale(0.8)!important;transform-origin:center!important}
#options_button,#send_but,#mes_stop,.stscript_btn,#mes_impersonate,#mes_continue{color:#A0A0A0!important;transition:color .2s ease!important}
#options_button:hover,#send_but:hover,#mes_stop:hover,.stscript_btn:hover,#mes_impersonate:hover,#mes_continue:hover{color:#333!important}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::after{content:"「今 日 小 雪」";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);color:#888;font-size:15px;font-style:italic;letter-spacing:4px;pointer-events:none;z-index:10}/* 🤍 */
#qr--bar{max-height:0;opacity:0;overflow:hidden;transition:.3s ease;pointer-events:none;border-radius:12px!important}
#send_form:focus-within #qr--bar{max-height:150px;opacity:1;pointer-events:auto;margin-bottom:5px}
#top-bar{height:34px!important;min-height:34px!important;background-color:transparent!important;box-shadow:none!important;border-bottom:none!important;display:flex!important;align-items:center!important;justify-content:center!important;padding:0!important;overflow:hidden!important}
.drawer-toggle{height:34px!important;width:44px!important;display:flex!important;align-items:center!important;justify-content:center!important;cursor:pointer!important;-webkit-tap-highlight-color:transparent}
.drawer-icon{font-size:0!important;display:block!important;width:24px!important;height:24px!important;background:url("https://files.catbox.moe/47eio1.png") center/contain no-repeat!important;opacity:1!important;filter:drop-shadow(1px 2px 2px rgba(0,0,0,0.3))!important;transition:transform .6s cubic-bezier(.34,1.56,.64,1)!important}/* 🤍 */
.drawer-toggle:hover .drawer-icon{transform:scale(1.1)!important;filter:drop-shadow(2px 3px 4px rgba(0,0,0,0.4))!important}
.drawer-toggle:active .drawer-icon{transform:scale(.9) rotate(360deg)!important;transition:transform .4s!important}
.drawer-icon *{display:none!important}
.top-bar-border{display:none!important}

/* 10.移动端 (对应更新位置数据，保证手机端同样完美对齐不重叠) */
@media screen and (max-width:800px){
#chat .mes{width:92%!important;padding:25px 20px 30px 40px!important;margin-left:auto!important;margin-right:auto!important;overflow:visible!important}
#chat .mes .mes_block{padding-left:15px!important}

/* 移动端楼层等元素美化同步 */
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{top:145px!important;font-size:10px!important}
#chat .mes .tokenCounterDisplay{right:25px!important}
#chat .mes .mes_timer{right:80px!important}
#chat .mes .mesIDDisplay{right:135px!important}
#chat .mes .mes_block::before{height:130px;margin-bottom:25px}
#chat .mes::before{left:4px!important;width:28px!important}

/* 移动端排版适配：更新为中轴安全定位 */
#chat .mes .avatar{top:90px!important;width:26px!important;height:26px!important;left:calc(50% - 17px)!important;margin-left:-4px!important}
#chat .mes .name_text{top:90px!important;font-size:16px!important;left:calc(50% - 17px)!important;margin-left:4px!important;padding:4px 12px!important}
#chat .mes .name_text::before{font-size:15px!important}

/* 移动端美化与位置调整 */
#chat .mes .timestamp{top:28px!important;left:55px!important}
#chat .mes .ch_name img, #chat .mes .model_logo{top:30px!important;left:205px!important;height:15px!important}

#chat .mes .mes_text::before{font-size:12px!important;margin-top:-35px!important;margin-bottom:20px!important}
#chat .mes .mes_buttons{bottom:15px!important;right:20px!important}
#chat .mes .mes_edit_buttons{right:20px!important;bottom:40px!important}
#chat .mes .mes_text{margin-top:25px!important;font-size:14px!important}
}

/* 12.全局提示窗口(Toast)适配：改为纯净浮窗风格 */
#toast-container>div{opacity:.98!important;background-color:#fff!important;color:#555!important;border:1px solid #ececec!important;border-radius:12px!important;box-shadow:0 8px 25px rgba(0,0,0,.05)!important;padding:12px 20px 12px 42px!important;background-image:none!important;min-height:auto!important;font-size:13.5px!important;font-weight:500!important}
/* 图标微调：使其更融入留白 */
#toast-container>div::before{content:""!important;position:absolute!important;left:10px!important;top:50%!important;transform:translateY(-50%)!important;width:22px!important;height:22px!important;background:url("https://files.catbox.moe/47eio1.png") center/contain no-repeat!important;filter:drop-shadow(0 1px 2px rgba(0,0,0,.05))!important}/* 🤍 */
.toast-title{font-weight:700!important;margin-bottom:2px!important}
.toast-message{line-height:1.4!important;opacity:.8!important}
